from collections import deque

# BFS (Level-order)
def bfs(root):
    if not root: return []
    res, q = [], deque([root])
    while q:
        node = q.popleft()
        res.append(node.val)
        if node.left: q.append(node.left)
        if node.right: q.append(node.right)
    return res

# DFS (Pre-order)
def dfs_preorder(root):
    return [root.val] + dfs_preorder(root.left) + dfs_preorder(root.right) if root else []

