public List<int> BFS(TreeNode root) {
    var res = new List<int>();
    if (root == null) return res;
    var q = new Queue<TreeNode>();
    q.Enqueue(root);
    while (q.Count > 0) {
        var curr = q.Dequeue();
        res.Add(curr.Value);
        if (curr.Left != null) q.Enqueue(curr.Left);
        if (curr.Right != null) q.Enqueue(curr.Right);
    }
    return res;
}

