def find_duplicates(arr):
    seen, dupes = set(), set()
    for x in arr:
        if x in seen: dupes.add(x)
        else: seen.add(x)
    return list(dupes)

# Array of chars: Bitmask for 'a'-'z'
def find_char_duplicates(chars):
    checker = 0
    dupes = set()
    for c in chars:
        bit = 1 << (ord(c) - ord('a'))
        if checker & bit: dupes.add(c)
        else: checker |= bit
    return list(dupes)

