// General vector duplicates
std::vector<int> findDuplicates(const std::vector<int>& arr) {
    std::unordered_set<int> seen, dupes;
    for (int x : arr) {
        if (!seen.insert(x).second) dupes.insert(x);
    }
    return std::vector<int>(dupes.begin(), dupes.end());
}

// Char array: fixed 256-element boolean map (O(1) space)
std::vector<char> findCharDuplicates(const std::vector<char>& chars) {
    bool seen[256] = {false};
    std::vector<char> dupes;
    for (char c : chars) {
        unsigned char uc = static_cast<unsigned char>(c);
        if (seen[uc]) dupes.push_back(c);
        else seen[uc] = true;
    }
    return dupes;
}

