using System.Collections.Generic;

// Iterative In-Order Traversal
public List<int> InorderIterative(TreeNode root) {
    var res = new List<int>();
    var stack = new Stack<TreeNode>();
    var curr = root;
    while (curr != null || stack.Count > 0) {
        while (curr != null) {
            stack.Push(curr);
            curr = curr.Left;
        }
        curr = stack.Pop();
        res.Add(curr.Value);
        curr = curr.Right;
    }
    return res;
}
